package ua.empirecraft.feudal;

import java.math.*;
import java.sql.SQLException;
import java.util.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import ua.empirecraft.feudal.FeudalService.Actor;

/** The army shares Feudal's one main-thread connection and exact provision ledger. */
public final class ArmyService {
    final FeudalService s; final Database db; final ProvisionService food; final PoliticsService politics;
    public java.util.function.BiPredicate<String,String> canDeclare=(a,b)->true;
    public ArmyService(FeudalService s,ProvisionService food,PoliticsService politics)throws SQLException{
        this.s=s;db=s.db;this.food=food;this.politics=politics;
        for(String ddl:List.of(
            "CREATE TABLE IF NOT EXISTS army_units(id VARCHAR(36) PRIMARY KEY,owner VARCHAR(36),original_owner VARCHAR(36),estate VARCHAR(80),home VARCHAR(80),loaded BOOLEAN,alive BOOLEAN,last_seen BIGINT,hunger DOUBLE,feed_seq BIGINT DEFAULT 0,feed_amount INT DEFAULT 0,feed_request INT DEFAULT 0,feed_total BIGINT DEFAULT 0)",
            "CREATE INDEX IF NOT EXISTS army_home ON army_units(home,alive)",
            "CREATE TABLE IF NOT EXISTS army_food_receipts(unit VARCHAR(36),seq BIGINT,amount INT,requested INT,PRIMARY KEY(unit,seq))",
            "CREATE TABLE IF NOT EXISTS army_factions(estate VARCHAR(80) PRIMARY KEY,seq BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE)",
            "CREATE TABLE IF NOT EXISTS army_officers(estate VARCHAR(80),person VARCHAR(36),PRIMARY KEY(estate,person))",
            "CREATE TABLE IF NOT EXISTS army_settings(estate VARCHAR(80) PRIMARY KEY,wage BIGINT,code VARCHAR(8),unit_limit INT,due BIGINT,unpaid_since BIGINT)",
            "CREATE TABLE IF NOT EXISTS army_payroll(estate VARCHAR(80),due BIGINT,amount BIGINT,code VARCHAR(8),troops BIGINT,paid BOOLEAN DEFAULT FALSE,PRIMARY KEY(estate,due))",
            "CREATE TABLE IF NOT EXISTS army_log(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,at_time BIGINT,estate VARCHAR(80),unit VARCHAR(36),actor VARCHAR(80),event VARCHAR(32),amount BIGINT,detail CLOB)",
            "CREATE INDEX IF NOT EXISTS army_log_time ON army_log(estate,at_time)",
            "CREATE TABLE IF NOT EXISTS army_wars(id VARCHAR(36) PRIMARY KEY,attacker VARCHAR(80),defender VARCHAR(80),status VARCHAR(16),created BIGINT,peace_a VARCHAR(36),peace_b VARCHAR(36))",
            "CREATE TABLE IF NOT EXISTS army_motions(id VARCHAR(36) PRIMARY KEY,estate VARCHAR(80),kind VARCHAR(16),args CLOB,fingerprint CLOB,electorate CLOB,deadline BIGINT,status VARCHAR(16))",
            "CREATE TABLE IF NOT EXISTS army_votes(motion VARCHAR(36),person VARCHAR(36),choice BOOLEAN,PRIMARY KEY(motion,person))"
        ))db.execute(ddl);
        db.execute("ALTER TABLE army_units ADD COLUMN IF NOT EXISTS pending_owner VARCHAR(36)");
        db.execute("ALTER TABLE army_units ADD COLUMN IF NOT EXISTS retired BOOLEAN DEFAULT FALSE");
        db.execute("INSERT INTO army_food_receipts(unit,seq,amount,requested) SELECT id,feed_seq,feed_amount,feed_request FROM army_units u WHERE feed_seq>0 AND NOT EXISTS(SELECT 1 FROM army_food_receipts r WHERE r.unit=u.id AND r.seq=u.feed_seq)");
        db.execute("UPDATE army_units SET loaded=FALSE");
    }
    public Map<String,Object> unit(String id)throws SQLException{return db.one("SELECT * FROM army_units WHERE id=?",id);}
    public String faction(String estate)throws SQLException{
        var r=db.one("SELECT seq FROM army_factions WHERE estate=?",estate);
        if(r==null){db.execute("INSERT INTO army_factions(estate) VALUES(?)",estate);r=db.one("SELECT seq FROM army_factions WHERE estate=?",estate);}
        return "ec_"+Long.toString(number(r,"seq"),36);
    }
    void log(String estate,String unit,String actor,String event,long amount,String detail)throws SQLException{db.execute("INSERT INTO army_log(at_time,estate,unit,actor,event,amount,detail) VALUES(?,?,?,?,?,?,?)",s.now(),estate,unit,actor,event,amount,detail);}
    public void observe(String id,String owner,String home,double hunger){db.transaction(()->{
        UUID.fromString(id);if(owner!=null)UUID.fromString(owner);require(Double.isFinite(hunger)&&hunger>=0&&hunger<=100,"Некоректний голод.");
        var u=unit(id);
        if(u==null){db.execute("INSERT INTO army_units(id,owner,original_owner,estate,home,loaded,alive,last_seen,hunger) VALUES(?,?,?,NULL,?,TRUE,TRUE,?,?)",id,owner,owner,home,s.now(),hunger);log(home,id,owner,"REGISTER",0,"Особистий загін");}
        else if(bool(u,"retired")){db.execute("UPDATE army_units SET alive=TRUE,retired=FALSE,owner=?,original_owner=?,estate=NULL,home=?,loaded=TRUE,last_seen=?,hunger=? WHERE id=?",owner,owner,home,s.now(),hunger,id);log(home,id,owner,"REENLIST",0,"Повторний найм");}
        else if(bool(u,"alive")){
            String garrison=string(u,"estate"),pendingOwner=string(u,"pending_owner");String effectiveOwner=pendingOwner==null?owner:pendingOwner;
            // Garrison allegiance is its estate, not the personal citizenship of a successor.
            db.execute("UPDATE army_units SET owner=?,home=?,loaded=TRUE,last_seen=?,hunger=?,pending_owner=?,original_owner=? WHERE id=?",garrison==null?effectiveOwner:s.estate(garrison).lord(),garrison==null?home:string(u,"home"),s.now(),hunger,Objects.equals(pendingOwner,owner)?null:pendingOwner,garrison==null&&pendingOwner==null?owner:string(u,"original_owner"),id);
        }
        return null;
    });}
    public void presence(String id,boolean dead){db.transaction(()->{var u=unit(id);if(u!=null){if(dead&&string(u,"estate")!=null)accrue(settings(string(u,"estate")));db.execute("UPDATE army_units SET loaded=FALSE,alive=?,last_seen=? WHERE id=?",!dead&&bool(u,"alive"),s.now(),id);if(dead)log(string(u,"home"),id,"сервер","DEATH",0,"Загибель рекрута");}return null;});}
    public void retire(String id){db.transaction(()->{var u=unit(id);if(u!=null&&bool(u,"alive")){if(string(u,"estate")!=null)accrue(settings(string(u,"estate")));db.execute("UPDATE army_units SET alive=FALSE,loaded=FALSE,retired=TRUE WHERE id=?",id);log(string(u,"home"),id,"сервер","RETIRED",0,"Виведено з активного війська");}return null;});}
    void ruler(Actor a,String estate)throws SQLException{require(s.estate(estate).active() && Objects.equals(a.id(),s.estate(estate).lord()),"Потрібні повноваження чинного правителя.");}
    public boolean commands(String actor,Map<String,Object> u)throws SQLException{
        if(u==null || !bool(u,"alive"))return false;String estate=string(u,"estate");
        return estate==null?Objects.equals(actor,string(u,"owner")):s.estate(estate).active() && (Objects.equals(actor,s.estate(estate).lord()) || db.one("SELECT person FROM army_officers WHERE estate=? AND person=?",estate,actor)!=null && citizen(actor,estate));
    }
    boolean citizen(String person,String estate)throws SQLException{
        if(politics==null)return Objects.equals(s.estate(estate).lord(),person)||s.citizen(person,s.estate(estate).nation());
        return politics.electorate(estate).contains(person);
    }
    public void assign(Actor a,String id,String estate,String home){db.transaction(()->{
        var u=unit(id);require(u!=null&&bool(u,"alive")&&bool(u,"loaded"),"Оберіть живого завантаженого рекрута.");
        ruler(a,estate);require(string(u,"estate")==null && Objects.equals(string(u,"owner"),a.id()),"Передати в гарнізон можна лише власного рекрута. Чужі особисті загони не вилучаються.");
        require(home!=null&&s.estate(home).active()&&home.startsWith("t:"),"Потрібне місто постачання.");
        require(sourceAllowed(estate,home),"Постачати гарнізон може лише власне місто правителя або прямо адміністроване місто; провізія васала не вилучається.");
        var settings=settings(estate);accrue(settings);long total=count("estate",estate,false);require(total<number(settings,"unit_limit"),"Ліміт гарнізону вичерпано.");
        db.execute("UPDATE army_units SET estate=?,home=?,owner=? WHERE id=?",estate,home,s.estate(estate).lord(),id);log(estate,id,a.id(),"GARRISON",0,"Постачання: "+home);return null;
    });}
    public boolean sourceAllowed(String estate,String home)throws SQLException{return s.estate(estate).active()&&s.estate(home).active()&&(estate.equals(home)||politics==null&&Objects.equals(s.estate(estate).lord(),s.estate(home).lord())||politics!=null&&politics.directTowns(estate).contains(home));}
    public void supply(Actor a,String estate,String home){db.transaction(()->{ruler(a,estate);require(home.startsWith("t:")&&sourceAllowed(estate,home),"Це не власне або прямо адміністроване місто постачання.");db.execute("UPDATE army_units SET home=? WHERE estate=? AND alive=TRUE",home,estate);log(estate,null,a.id(),"SUPPLY_CITY",0,home);return null;});}
    public String release(Actor a,String id){return db.transaction(()->{var u=unit(id);require(u!=null&&string(u,"estate")!=null,"Це не гарнізонний рекрут.");String estate=string(u,"estate");require(s.estate(estate).active()?Objects.equals(a.id(),s.estate(estate).lord()):Objects.equals(a.id(),string(u,"original_owner")),"Повернути гарнізон може правитель; з архівного володіння — первісний власник.");accrue(settings(estate));String owner=string(u,"original_owner");require(owner!=null,"Первісного власника не встановлено.");db.execute("UPDATE army_units SET estate=NULL,owner=?,pending_owner=?,home=NULL WHERE id=?",owner,owner,id);log(estate,id,a.id(),"RELEASE",0,"Повернення власнику "+owner);return owner;});}
    public void officer(Actor a,String estate,String person,boolean add){db.transaction(()->{ruler(a,estate);UUID.fromString(person);require(!add||citizen(person,estate),"Воєначальник має бути громадянином володіння.");if(add)db.execute("MERGE INTO army_officers KEY(estate,person) VALUES(?,?)",estate,person);else db.execute("DELETE FROM army_officers WHERE estate=? AND person=?",estate,person);log(estate,null,a.id(),"OFFICER",0,person+" "+add);return null;});}
    public Map<String,Object> settings(String estate)throws SQLException{
        var r=db.one("SELECT * FROM army_settings WHERE estate=?",estate);
        if(r==null){db.execute("INSERT INTO army_settings VALUES(?,0,'-',200,?,0)",estate,s.now()+FeudalService.DAY);r=db.one("SELECT * FROM army_settings WHERE estate=?",estate);}return r;
    }
    public long count(String field,String id,boolean loaded)throws SQLException{require(Set.of("home","estate","owner").contains(field),"Невідомий тип обліку.");return number(db.one("SELECT COUNT(*) AS n FROM army_units WHERE "+field+"=? AND alive=TRUE"+(loaded?" AND loaded=TRUE":""),id),"n");}
    /** Idempotent receipt: the entity persists its sequence together with hunger in the same NBT. */
    public int feed(String id,long seq,int requested){return db.transaction(()->{
        var u=unit(id);require(u!=null&&bool(u,"alive")&&bool(u,"loaded"),"Немає живого зареєстрованого рекрута.");require(requested>=1&&requested<=20&&seq>0,"Некоректна порція.");
        long last=number(u,"feed_seq");if(seq<=last){var receipt=db.one("SELECT * FROM army_food_receipts WHERE unit=? AND seq=?",id,seq);require(receipt!=null&&requested==number(receipt,"requested"),"Невідома квитанція або змінилися параметри повторного запиту.");return (int)number(receipt,"amount");}require(seq==last+1,"Пропущена або застаріла квитанція харчування.");
        String home=string(u,"home");if(string(u,"estate")!=null&&(home==null||!sourceAllowed(string(u,"estate"),home)))return 0;if(home==null||food.town(home)==null||food.pending(home)||!s.estate(home).active())return 0;
        BigInteger available=food.reserve(home).divide(ProvisionClock.UNIT);int grant=available.min(BigInteger.valueOf(requested)).intValueExact();if(grant==0)return 0;
        BigInteger remaining=ProvisionClock.UNIT.multiply(BigInteger.valueOf(grant)),credit=ProvisionService.energy(food.town(home),"credit");BigInteger used=credit.min(remaining);credit=credit.subtract(used);remaining=remaining.subtract(used);
        for(var row:food.stock(home)){
            if(remaining.signum()==0)break;BigInteger one=ProvisionClock.UNIT.multiply(BigInteger.valueOf(number(row,"nutrition")));
            int n=remaining.add(one).subtract(BigInteger.ONE).divide(one).min(BigInteger.valueOf(number(row,"quantity"))).intValueExact();BigInteger taken=one.multiply(BigInteger.valueOf(n));used=taken.min(remaining);remaining=remaining.subtract(used);credit=credit.add(taken.subtract(used));
            db.execute("UPDATE provision_stock SET quantity=quantity-?,version=version+1 WHERE town=? AND slot=?",n,home,number(row,"slot"));
        }
        require(remaining.signum()==0,"Змінився запас провізії.");db.execute("UPDATE provision_towns SET credit=? WHERE town=?",new BigDecimal(credit),home);
        db.execute("INSERT INTO army_food_receipts VALUES(?,?,?,?)",id,seq,grant,requested);db.execute("UPDATE army_units SET feed_seq=?,feed_amount=?,feed_request=?,feed_total=feed_total+? WHERE id=?",seq,grant,requested,grant,id);log(home,id,"постачання","FOOD",grant,"З міської провізії; квитанція "+seq);return grant;
    });}
    public String propose(Actor a,String estate,String kind,String args){return db.transaction(()->{
        ruler(a,estate);validatePlan(estate,kind,args);boolean council=politics!=null&&Set.of(PoliticalModel.Government.REPUBLIC,PoliticalModel.Government.TRIBAL_COUNCIL).contains(politics.state(estate).government());
        if(!council){apply(a,estate,kind,args);return "APPLIED";}
        var voters=politics.electorate(estate);require(!voters.isEmpty(),"Немає складу ради.");String id=UUID.randomUUID().toString();db.execute("INSERT INTO army_motions VALUES(?,?,?,?,?,?,?,'OPEN')",id,estate,kind,args,politics.fingerprint(estate),String.join(",",new TreeSet<>(voters)),s.now()+2*FeudalService.DAY);log(estate,null,a.id(),"COUNCIL",0,id+" "+kind+" "+args);return id;
    });}
    void validatePlan(String estate,String kind,String args)throws SQLException{
        String[] p=args.split(" ");
        switch(kind){
            case "WAGE"->{require(p.length==3,"План утримання: сума код ліміт.");long n=Model.money(p[0]);int limit=Integer.parseInt(p[2]);require(limit>=1&&limit<=10000,"Ліміт: 1–10000.");require(n<=Long.MAX_VALUE/Math.max(limit,count("estate",estate,false)),"Ставка завелика для чисельності гарнізону.");if(n>0)s.currency(p[1]);}
            case "WAR"->{require(canDeclare.test(estate,args),"Війна неможлива: союз, договір про ненапад або дані дипломатії ще оновлюються.");require(p.length==1&&!estate.equals(p[0])&&s.estate(p[0]).active(),"Оберіть інше чинне володіння.");require(s.parent(estate)==null || s.contractBuilder!=null&&s.contractBuilder.active(estate)!=null || s.contract(estate)!=null&&"висока".equals(string(s.contract(estate),"autonomy")),"Підлеглому володінню потрібен договір із правом оголошення війни.");require(!sameRealm(estate,p[0]),"Не можна оголосити війну власному володінню чи васальному дому.");}
            case "PEACE"->{var w=war(args);require(List.of(string(w,"attacker"),string(w,"defender")).contains(estate),"Володіння не є стороною війни.");}
            default->throw new IllegalArgumentException("Невідомий план ради.");
        }
    }
    public void vote(Actor a,String id,boolean yes){db.transaction(()->{
        var m=db.one("SELECT * FROM army_motions WHERE id=?",id);require(m!=null&&"OPEN".equals(string(m,"status"))&&number(m,"deadline")>s.now(),"Рішення закрито або строк минув.");String estate=string(m,"estate");
        require(Objects.equals(string(m,"fingerprint"),politics.fingerprint(estate)),"Склад чи повноваження змінилися; потрібне нове рішення.");var voters=Set.of(string(m,"electorate").split(","));require(voters.contains(a.id())&&politics.electorate(estate).contains(a.id()),"Ви не виборець цієї ради.");db.execute("MERGE INTO army_votes KEY(motion,person) VALUES(?,?,?)",id,a.id(),yes);
        long positives=number(db.one("SELECT COUNT(*) AS n FROM army_votes WHERE motion=? AND choice=TRUE",id),"n"),negatives=number(db.one("SELECT COUNT(*) AS n FROM army_votes WHERE motion=? AND choice=FALSE",id),"n");
        if(positives>voters.size()/2){apply(new Actor(s.estate(estate).lord(),false),estate,string(m,"kind"),string(m,"args"));db.execute("UPDATE army_motions SET status='APPLIED' WHERE id=?",id);}else if(negatives>= (voters.size()+1)/2)db.execute("UPDATE army_motions SET status='REJECTED' WHERE id=?",id);return null;
    });}
    void apply(Actor a,String estate,String kind,String args)throws SQLException{
        validatePlan(estate,kind,args);String[] p=args.split(" ");switch(kind){
            case "WAGE"->{long wage=Model.money(p[0]);var old=settings(estate);accrue(old);require(number(settings(estate),"due")>s.now(),"Триває облік попередніх діб утримання; повторіть після синхронізації.");db.execute("UPDATE army_settings SET wage=?,code=?,unit_limit=?,due=? WHERE estate=?",wage,p[1],Integer.parseInt(p[2]),s.now()+FeudalService.DAY,estate);}
            case "WAR"->{if(s.contractBuilder!=null)s.contractBuilder.autonomy(estate,"war");require(db.one("SELECT id FROM army_wars WHERE status='ACTIVE' AND ((attacker=? AND defender=?) OR(attacker=? AND defender=?))",estate,args,args,estate)==null,"Така війна вже триває.");db.execute("INSERT INTO army_wars VALUES(?,?,?,'ACTIVE',?,NULL,NULL)",UUID.randomUUID().toString(),estate,args,s.now());}
            case "PEACE"->{var w=war(args);String side=estate.equals(string(w,"attacker"))?"peace_a":"peace_b";db.execute("UPDATE army_wars SET "+side+"=? WHERE id=?",a.id(),args);w=war(args);if(Objects.equals(string(w,"peace_a"),s.estate(string(w,"attacker")).lord())&&Objects.equals(string(w,"peace_b"),s.estate(string(w,"defender")).lord()))db.execute("UPDATE army_wars SET status='PEACE' WHERE id=?",args);}
        }log(estate,null,a.id(),kind,0,args);
    }
    public Map<String,Object> war(String id)throws SQLException{var w=db.one("SELECT * FROM army_wars WHERE id=? AND status='ACTIVE'",id);require(w!=null,"Чинну війну не знайдено.");return w;}
    public boolean sameRealm(String a,String b)throws SQLException{
        var aa=ancestors(a);var bb=ancestors(b);for(String x:aa)if(bb.contains(x))return true;
        String na=s.estate(a).nation(),nb=s.estate(b).nation();return na!=null&&na.equals(nb);
    }
    Set<String> ancestors(String estate)throws SQLException{var out=new HashSet<String>();for(String e=estate;e!=null&&out.add(e);e=s.parent(e)){}return out;}
    public void tick(){db.transaction(()->{
        db.execute("UPDATE army_units SET loaded=FALSE WHERE loaded=TRUE AND last_seen<?",s.now()-10000);
        db.execute("UPDATE army_motions SET status='EXPIRED' WHERE status='OPEN' AND deadline<?",s.now());
        for(var u:db.query("SELECT * FROM army_units WHERE alive=TRUE AND estate IS NOT NULL")){
            String estate=string(u,"estate");if(s.estate(estate).active())db.execute("UPDATE army_units SET owner=? WHERE id=?",s.estate(estate).lord(),string(u,"id"));
        }
        for(var st:db.query("SELECT * FROM army_settings"))if(s.estate(string(st,"estate")).active())accrue(st);
        for(var bill:db.query("SELECT * FROM army_payroll WHERE paid=FALSE ORDER BY due,estate")){
            String estate=string(bill,"estate"),code=string(bill,"code");long amount=number(bill,"amount");
            if(amount>0&&s.balance("e:"+estate,code)<amount)continue;
            if(amount>0)s.restore("e:"+estate,"army:"+estate,code,amount);
            db.execute("UPDATE army_payroll SET paid=TRUE WHERE estate=? AND due=?",estate,number(bill,"due"));log(estate,null,"скарбниця","WAGE",amount,number(bill,"troops")+" рекрутів; "+code);
        }
        for(var st:db.query("SELECT estate FROM army_settings")){
            String estate=string(st,"estate");var late=db.one("SELECT MIN(due) AS n FROM army_payroll WHERE estate=? AND paid=FALSE",estate);db.execute("UPDATE army_settings SET unpaid_since=? WHERE estate=?",late.get("n")==null?0:number(late,"n"),estate);
        }return null;
    });}
    void accrue(Map<String,Object> st)throws SQLException{
        String estate=string(st,"estate");long due=number(st,"due");if(due>s.now())return;
        if(number(st,"wage")==0){db.execute("UPDATE army_settings SET due=? WHERE estate=?",s.now()+FeudalService.DAY,estate);return;}
        long count=count("estate",estate,false),amount=Math.multiplyExact(number(st,"wage"),count);
        long periods=1+(s.now()-due)/FeudalService.DAY,next=Math.addExact(due,Math.multiplyExact(periods,FeudalService.DAY));
        // Persist every elapsed invoice before a roster change, including long server downtime.
        db.execute("INSERT INTO army_payroll(estate,due,amount,code,troops) SELECT ?,?+r.n*?,?,?,? FROM SYSTEM_RANGE(0,?) r(n) WHERE NOT EXISTS(SELECT 1 FROM army_payroll p WHERE p.estate=? AND p.due=?+r.n*?)",estate,due,FeudalService.DAY,amount,string(st,"code"),count,periods-1,estate,due,FeudalService.DAY);
        db.execute("UPDATE army_settings SET due=? WHERE estate=?",next,estate);
    }
    public List<Map<String,Object>> history(String estate,int page)throws SQLException{require(page>=0&&page<100000,"Невірна сторінка.");return db.query("SELECT * FROM army_log WHERE estate=? ORDER BY seq DESC LIMIT 30 OFFSET ?",estate,page*30);}
}
